-- Apex AMC :: 100 - Published-data snapshot (GENERATED, do not edit)
--
-- Generated by scripts/export-d1.mjs from data/published/manifest.json.
-- Regenerate with: npm run data:snapshot
--
-- Every row identifies one archived published document by SHA-256, byte
-- length and canonical URL. `content` is inlined only for documents under
-- the inline limit (see the header of scripts/export-d1.mjs for why the
-- larger third-party documents are identified rather than reproduced).

CREATE TABLE IF NOT EXISTS published_documents (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    file        TEXT NOT NULL UNIQUE,
    url         TEXT NOT NULL,
    publisher   TEXT NOT NULL,
    title       TEXT NOT NULL,
    doc_type    TEXT NOT NULL,
    year        INTEGER,
    source_kind TEXT NOT NULL CHECK (source_kind IN ('primary', 'compilation', 'community')),
    optional    INTEGER NOT NULL DEFAULT 0 CHECK (optional IN (0, 1)),
    sha256      TEXT,
    bytes       INTEGER NOT NULL DEFAULT 0,
    content     BLOB,
    archived_on TEXT NOT NULL DEFAULT (date('now'))
);

CREATE INDEX IF NOT EXISTS idx_published_documents_kind ON published_documents(source_kind);
CREATE INDEX IF NOT EXISTS idx_published_documents_sha   ON published_documents(sha256);

